# wire_demo: clear-sign an ERC-7730 wire-format request on the Pico wallet (emulator or board).
# Emulator: tools/emu run wire_demo    keys: up/down scroll, left/right switch request, A approve, Y reject, X quit
# The request bytes below were made by wire_encode.py (host). ROOT is the toy root-of-trust P-256 key.
import time, binascii
from machine import Timer
from lcd import LCD, Keys, BLACK, WHITE, GREEN, RED, YELLOW, GREY, DARK
import wire_decode

ROOT = (0x5aad93ec83ddd9ff96b7e0c1ce1fd23211a80324b5656799f1c28ec387b782e1, 0xcffffd54411d37d45fc5996d6572642f991eebf44b96e86b79015ec1db365de0)
REQS = [
    ("usds-transfer", ""),
    ("batch", ""),
]

lcd = LCD()
keys = Keys()
timer = None
which, top, rows, status, t_load = 0, 0, [], "", 0

def load():
    global rows, top, status, t_load
    name, hexs = REQS[which]
    t0 = time.ticks_ms()
    try:
        rows = wire_decode.render(binascii.unhexlify(hexs), ROOT)
        status = ""
    except Exception as e:
        rows = [(0, "error", str(e))]
        status = "decode failed"
    t_load = time.ticks_diff(time.ticks_ms(), t0)
    top = 0
    print("loaded", name, len(hexs) // 2, "bytes in", t_load, "ms")
    for d, l, t in rows:
        print("  " * d + l + ": " + t)

def wrap(s, n):
    return [s[i:i + n] for i in range(0, len(s), n)] or [""]

def draw():
    lcd.fill(BLACK)
    lcd.fill_rect(0, 0, 240, 18, DARK)
    lcd.text(REQS[which][0], 4, 5, YELLOW)
    lcd.text("%dms" % t_load, 190, 5, GREY)
    y = 24
    lines = []
    for depth, label, text in rows:
        x = 4 + depth * 12
        bad = "BAD SIGNATURE" in text
        lines.append((x, label, GREY if not bad else RED, False))
        for part in wrap(text, (232 - x) // 8):
            lines.append((x, part, RED if bad else WHITE, True))
    for (x, s, c, val) in lines[top:top + 16]:
        lcd.text(s, x + (8 if val else 0), y, c)
        y += 11
        if y > 208:
            break
    lcd.fill_rect(0, 218, 240, 22, DARK)
    if status:
        lcd.center_text(status, 226, YELLOW)
    else:
        lcd.center_text("A sign   Y reject", 226, GREEN)
    lcd.show()

def tick(_):
    global which, top, status
    for k in keys.pressed():
        if k == "X":
            stop(); return
        if k == "down": top += 1
        if k == "up": top = max(0, top - 1)
        if k in ("left", "right"):
            which = (which + (1 if k == "right" else -1)) % len(REQS); load()
        if k == "A":
            status = "signed (toy: no chip call)"
        if k == "Y":
            status = "rejected"
    draw()

def start():
    global timer
    load(); draw()
    timer = Timer(period=60, mode=Timer.PERIODIC, callback=tick)

def stop():
    global timer
    if timer:
        timer.deinit(); timer = None
    lcd.center_text("bye", 120, GREY); lcd.show()

start()
